// frontend/src/api/schemas.ts
// Friendly names for the generated OpenAPI schemas. types.ts is regenerated by `pnpm --filter frontend gen:api`,
// so aliases live here instead of in the generated file.

import type { components } from './types';

type Schemas = components['schemas'];

export type HealthResponse = Schemas['Health'];
export type ApiError = Schemas['ErrorResponse'];
export type EnumsResponse = Schemas['Enums'];
export type EnumOption = Schemas['EnumOption'];
export type ChainInfoResponse = Schemas['ChainInfo'];
export type CredentialSchemasResponse = Schemas['CredentialSchemaList'];
export type CredentialSchema = Schemas['CredentialSchema'];
export type CredentialSchemaField = Schemas['CredentialSchemaField'];

export type Issuer = Schemas['Issuer'];
export type IssuerKey = Schemas['IssuerKey'];
export type IssuerCreate = Schemas['IssuerCreate'];
export type IssuerKind = Schemas['IssuerKind'];
export type IssuersListResponse = Schemas['IssuerList'];

// Contracts mirror md/CONTRACTS.md §3.2 & §3.6
export interface Batch {
  batch_id: string;
  issuer_id: string;
  key_id: string;
  size: number;
  status: 'open' | 'anchored';
  root: string | null;
  anchored_at: string | null;
  tx_hash: string | null;
}

export interface BatchesListResponse {
  items: Batch[];
}

export interface IssuedCredential {
  id: string;
  credential_type: string;
  wallet_id: string;
  batch_id: string;
  status_index: number;
  commitment: string;
  key_id: string;
  issued_at: string;
  revoked_at: string | null;
}

export interface IssuedCredentialsListResponse {
  items: IssuedCredential[];
  next_cursor?: string | null;
}

export interface IssueCredentialIn {
  credential_type: string;
  wallet_id: string;
  claims: Record<string, string | number>;
}

export interface IssueCredentialOut {
  credential_id: string;
  offer_id: string;
  batch_id: string;
  status_list_id: string;
  status_index: number;
  commitment: string;
}

export interface WalletLookupResponse {
  id: string;
  display_name: string;
  enc_public_key: string;
}

export interface WalletCreateIn {
  display_name: string;
  enc_public_key: string;
}

export interface WalletCreated {
  id: string;
  display_name: string;
  wallet_token: string;
}

export interface CredentialOffer {
  id: string;
  wallet_id: string;
  issuer_id: string;
  credential_type: string;
  ephemeral_public_key: string;
  iv: string;
  ciphertext: string;
  created_at: string;
  claimed_at: string | null;
}

export interface OffersListResponse {
  items: CredentialOffer[];
}

export interface BackupIn {
  ciphertext: string;
  iv: string;
  salt: string;
  kdf_iterations: number;
  version: number;
}

export interface Backup {
  wallet_id: string;
  ciphertext: string;
  iv: string;
  salt: string;
  kdf_iterations: number;
  version: number;
  updated_at: string;
}

// Verifiers & Requests (CONTRACTS §3.4 & §3.6)
export interface Verifier {
  id: string;
  name: string;
  did: string;
  created_at: string;
}

export interface VerifierCreateIn {
  name: string;
}

export interface VerifiersListResponse {
  items: Verifier[];
}

export interface PresentationRequirement {
  id: string;
  credential_type: string;
  accredited_only: boolean;
  issuer_kinds: string[] | null;
  issuer_dids: string[] | null;
  reveal: string[];
  equals: { field: string; value: string }[];
  predicates: { type: string; years: number }[];
  require_not_revoked: boolean;
}

export interface PresentationPolicy {
  purpose: string;
  requirements: PresentationRequirement[];
  never_collect: string[];
}

export interface ParseIn {
  text: string;
}

export interface ParseOut {
  policy: PresentationPolicy;
  consent_summary: string;
  minimisation_notes: string[];
}

export interface RequestCreateIn {
  verifier_id: string;
  policy: PresentationPolicy;
  nl_text: string | null;
}

export interface PresentationRequest {
  id: string;
  verifier_id: string;
  verifier_name: string;
  policy: PresentationPolicy;
  consent_summary: string;
  nonce: string;
  expires_at: string;
  created_at: string;
  wallet_url: string;
}

export interface VerificationStepResult {
  requirement_id: string;
  step: string;
  ok: boolean;
  code: string;
  message: string;
}

export interface Verification {
  id: string;
  request_id: string;
  mode: 'full' | 'naive';
  result: 'accepted' | 'rejected';
  steps: VerificationStepResult[];
  revealed: Record<string, Record<string, string>>;
  created_at: string;
}

export interface VerificationsListResponse {
  items: Verification[];
}
